/**
 * Emits src/styles/tokens.css — CSS custom properties mirrored from tokens.ts.
 *
 * tokens.ts stays the single source of truth; this file is generated output
 * (`npm run tokens:css`) so CSS layers (theme.css aliases, tailwind) consume
 * the same values without hand-duplicating them. Run it whenever token VALUES
 * change; new token GROUPS need a line here.
 */
import { writeFileSync } from "node:fs";
import { T, border, ease, lwir, motion, radius, shadow, space, surface } from "../src/app/tokens";

const lines: string[] = [
  "/* GENERATED by `npm run tokens:css` — do not edit. Source: src/app/tokens.ts */",
  ":root {",
];

const push = (name: string, value: string | number) => {
  lines.push(`  --sentinel-${name}: ${value};`);
};

Object.entries(T).forEach(([k, v]) => push(k.toLowerCase(), v));
Object.entries(lwir).forEach(([k, v]) => push(`lwir-${k}`, v));
Object.entries(surface).forEach(([k, v]) => push(`surface-${k}`, v));
Object.entries(border).forEach(([k, v]) => push(`border-${k}`, v));
Object.entries(radius).forEach(([k, v]) => push(`radius-${k}`, `${v}px`));
Object.entries(space).forEach(([k, v]) => push(`space-${k}`, `${v}px`));
Object.entries(ease).forEach(([k, v]) => push(`ease-${k}`, v));
Object.entries(motion).forEach(([k, v]) => push(`motion-${k}`, v));
Object.entries(shadow).forEach(([k, v]) => push(`shadow-${k}`, v));

lines.push("}");

writeFileSync(new URL("../src/styles/tokens.css", import.meta.url), lines.join("\n") + "\n");
console.log(`tokens.css written (${lines.length - 2} properties)`);
